def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    x = np.array([np.random.uniform(lb, ub) for _ in range(dim)])
    best_x = x.copy()
    temp = 1.0
    step_size = 1.0

    for i in range(budget):
        new_x = x + rng.normal(0, step_size, size=dim)
        new_x = clip(new_x, lb, ub)

        delta = func(new_x) - func(x)
        if delta < 0 or (delta >= 0 and np.random.rand() < np.exp(-delta / temp)):
            x = new_x
            if func(x) < func(best_x):
                best_x = x

        # Update temperature and step size
        temp *= 0.99
        step_size *= 0.9

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = (np.random.rand(dim) * 2 - 1) * ub + lb
    best_x = x.copy()
    best_f = func(x)

    for i in range(budget):
        d = np.zeros(dim)
        for j in range(dim):
            if rng.uniform(0, 1) < 0.5:
                d[j] = rng.uniform(-ub, ub)
            else:
                d[j] = rng.uniform(lb - best_x[j], ub - best_x[j])

        x_perturbed = clip(x + d)
        f_perturbed = func(x_perturbed)

        if f_perturbed < best_f:
            best_x = x_perturbed.copy()
            best_f = f_perturbed

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=dim)
    T = 1e2
    alpha = 0.99
    for _ in range(budget):
        y = x + np.random.uniform(-T, T, size=dim) / (1 + func(x))
        y = np.clip(y, lb, ub)
        T *= alpha
        if func(y) < func(x):
            x = y
        elif np.random.rand() < np.exp((func(x) - func(y)) / T):
            x = y
    return x
